  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL
);

// Database migration runner
//
// Reads SQL files from ./migrations/ and logs each filename it would apply,
// in lexicographic order. This is a dry-run logger: it does not execute SQL
// against any database. Name your migration files with a sortable prefix,
// e.g. 001_create_users.sql, 002_add_created_at.sql.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  return fs
    .readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
}

function migrate() {
  const files = getMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${files.length} migration(s). Applying in order:\n`);

  files.forEach((file, index) => {
    const step = String(index + 1).padStart(2, '0');
    console.log(`[${step}] Applying migration: ${file}`);
    // In a real runner, you would read and execute the SQL here:
    //   const sql = fs.readFileSync(path.join(MIGRATIONS_DIR, file), 'utf8');
    //   await client.query(sql);
  });

  console.log('\nDone. All migrations logged.');
}

if (require.main === module) {
  migrate();
}

module.exports = { migrate, getMigrationFiles };

