#!/usr/bin/env node
// migrate.js — reads SQL migration files from ./migrations/ and logs
// each filename it would apply, in order.
//
// This is a dry-run logger: it does NOT execute any SQL or connect to a
// database. It simply discovers and orders the migration files.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Compare two migration filenames so that any numeric prefix sorts
 * numerically (e.g. "2_..." before "10_..."), falling back to a plain
 * locale comparison when there's no numeric prefix.
 */
function compareMigrations(a, b) {
  const numA = parseInt(a, 10);
  const numB = parseInt(b, 10);
  const aHasNum = !Number.isNaN(numA);
  const bHasNum = !Number.isNaN(numB);

  if (aHasNum && bHasNum && numA !== numB) {
    return numA - numB;
  }
  return a.localeCompare(b, undefined, { numeric: true });
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  return fs
    .readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort(compareMigrations);
}

function main() {
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exitCode = 1;
    return;
  }

  if (files.length === 0) {
    console.log('No migrations found in ./migrations/');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);
  files.forEach((file, index) => {
    const step = String(index + 1).padStart(2, '0');
    console.log(`  [${step}] Would apply: ${file}`);
  });
  console.log('\nDry run complete. No SQL was executed.');
}

main();

module.exports = { getMigrationFiles, compareMigrations };

