#!/usr/bin/env node
// Database migration runner.
//
// Reads .sql files from ./migrations/ and logs each one it would apply,
// in ascending order. This is a dry-run: it only logs filenames and does
// not execute any SQL or connect to a database.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Return the list of migration filenames in the order they should be applied.
 * Files are sorted numerically by their leading numeric prefix when present,
 * falling back to a stable lexicographic comparison.
 */
function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  return fs
    .readdirSync(dir)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => {
      const na = parseInt(a, 10);
      const nb = parseInt(b, 10);
      if (!Number.isNaN(na) && !Number.isNaN(nb) && na !== nb) {
        return na - nb;
      }
      return a.localeCompare(b);
    });
}

function main() {
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migrations found in ./migrations/');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:`);
  files.forEach((file, i) => {
    const step = String(i + 1).padStart(2, '0');
    console.log(`  [${step}] would apply: ${file}`);
  });
  console.log('Done (dry-run: no SQL executed).');
}

if (require.main === module) {
  main();
}

module.exports = { getMigrationFiles };

