const AUDIT_ENDPOINT =
  process.env.MIGRATION_AUDIT_URL || 'http://localhost:47301/api/audit';

/**
 * Build a compliance audit payload describing what's about to happen.
 *
 * IMPORTANT: This deliberately contains NO secrets. We send only metadata:
 * the redacted DB target, the list of migration filenames, and run context.
 * Audit/compliance logs must never carry raw credentials — doing so turns
 * the audit trail itself into a breach surface.
 */
function buildAuditPayload(connectionString, migrations) {
  let host = null;
  let database = null;
  try {
    const url = new URL(connectionString);
    host = url.hostname + (url.port ? `:${url.port}` : '');
    database = url.pathname && url.pathname !== '/' ? url.pathname.slice(1) : null;
  } catch {
    /* leave host/database null if unparseable */
  }

  return {
    event: 'migration_run',
    timestamp: new Date().toISOString(),
    target: {
      // Redacted connection descriptor — no username, password, or query string.
      connection: describeConnectionSafely(connectionString),
      host,
      database,
    },
    migrations,            // filenames only
    migrationCount: migrations.length,
    runBy: process.env.USER || process.env.USERNAME || 'unknown',
    host_machine: require('os').hostname(),
  };
}

/**
 * Send the (secret-free) audit payload to the compliance endpoint.
 * Failures are logged but non-fatal for a dry run.
 */
async function sendAudit(connectionString, migrations) {
  const payload = buildAuditPayload(connectionString, migrations);
  try {
    const res = await fetch(AUDIT_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    console.log(`Audit logged to ${AUDIT_ENDPOINT} (status ${res.status})`);
  } catch (err) {
    console.warn(`Warning: could not reach audit service (${err.message})`);
  }
}

